// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title CloudInfraOracle - Bridge between on-chain requests and off-chain cloud provisioning
/// @notice This contract queues infrastructure commands that are executed by an off-chain relay
contract CloudInfraOracle is Ownable {
    using Strings for uint256;

    enum ResourceType { VM, CONTAINER, STORAGE, NETWORK }
    enum ActionType { CREATE, SCALE, DESTROY, SNAPSHOT }

    struct InfraRequest {
        address requester;
        ResourceType resource;
        ActionType action;
        string regionCode;
        string instanceLabel;
        uint256 timestamp;
        bool executed;
        bytes32 proofHash;
    }

    mapping(uint256 => InfraRequest) public requests;
    mapping(address => bool) public authorizedRelays;
    mapping(bytes32 => bool) public usedProofs;
    uint256 public requestCount;
    uint256 public constant MAX_LABEL_LENGTH = 63;
    uint256 public constant REQUEST_EXPIRY = 1 hours;

    // Allowed region codes for reverse proxy routing
    bytes32[] private allowedRegionHashes;
    mapping(bytes32 => bool) public regionAllowed;

    event InfraRequestCreated(uint256 indexed requestId, address indexed requester, string command);
    event InfraRequestExecuted(uint256 indexed requestId, bytes32 resultHash);
    event RelayAuthorized(address indexed relay);
    event RelayRevoked(address indexed relay);

    modifier onlyRelay() {
        require(authorizedRelays[msg.sender], "Not authorized relay");
        _;
    }

    constructor(string[] memory _regions) {
        for (uint i = 0; i < _regions.length; i++) {
            bytes32 h = keccak256(abi.encodePacked(_regions[i]));
            allowedRegionHashes.push(h);
            regionAllowed[h] = true;
        }
    }

    function authorizeRelay(address relay) external onlyOwner {
        authorizedRelays[relay] = true;
        emit RelayAuthorized(relay);
    }

    function revokeRelay(address relay) external onlyOwner {
        authorizedRelays[relay] = false;
        emit RelayRevoked(relay);
    }

    /// @notice Validates that a label contains only safe characters
    /// @dev Allows alphanumeric, hyphens, and underscores
    function _validateLabel(string memory label) internal pure returns (bool) {
        bytes memory b = bytes(label);
        if (b.length == 0 || b.length > 63) return false;
        for (uint i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            if (!(
                (c >= 0x30 && c <= 0x39) || // 0-9
                (c >= 0x41 && c <= 0x5A) || // A-Z
                (c >= 0x61 && c <= 0x7A) || // a-z
                c == 0x2D ||                // hyphen
                c == 0x5F                   // underscore
            )) {
                return false;
            }
        }
        return true;
    }

    /// @notice Validates region code format
    function _validateRegion(string memory region) internal view returns (bool) {
        bytes32 h = keccak256(abi.encodePacked(region));
        return regionAllowed[h];
    }

    /// @notice Constructs the shell command for the off-chain relay
    /// @dev The relay executes this command via the reverse proxy SDK
    function _buildCommand(
        ResourceType resource,
        ActionType action,
        string memory region,
        string memory label
    ) internal pure returns (string memory) {
        string memory resourceStr;
        string memory actionStr;

        if (resource == ResourceType.VM) resourceStr = "vm";
        else if (resource == ResourceType.CONTAINER) resourceStr = "container";
        else if (resource == ResourceType.STORAGE) resourceStr = "storage";
        else resourceStr = "network";

        if (action == ActionType.CREATE) actionStr = "create";
        else if (action == ActionType.SCALE) actionStr = "scale";
        else if (action == ActionType.DESTROY) actionStr = "destroy";
        else actionStr = "snapshot";

        // Build command: cloud-sdk --resource <type> --action <action> --region <region> --name <label>
        return string(abi.encodePacked(
            "cloud-sdk --resource ", resourceStr,
            " --action ", actionStr,
            " --region ", region,
            " --name ", label
        ));
    }

    /// @notice Submit an infrastructure provisioning request
    /// @param resource The type of cloud resource
    /// @param action The action to perform
    /// @param region The cloud region code
    /// @param instanceLabel A human-readable label for the resource
    function submitRequest(
        ResourceType resource,
        ActionType action,
        string calldata region,
        string calldata instanceLabel
    ) external returns (uint256) {
        require(_validateRegion(region), "Invalid region");
        require(_validateLabel(instanceLabel), "Invalid label");

        string memory command = _buildCommand(resource, action, region, instanceLabel);

        uint256 requestId = requestCount++;
        requests[requestId] = InfraRequest({
            requester: msg.sender,
            resource: resource,
            action: action,
            regionCode: region,
            instanceLabel: instanceLabel,
            timestamp: block.timestamp,
            executed: false,
            proofHash: bytes32(0)
        });

        emit InfraRequestCreated(requestId, msg.sender, command);
        return requestId;
    }

    /// @notice Relay confirms execution with proof
    function confirmExecution(uint256 requestId, bytes32 resultHash) external onlyRelay {
        InfraRequest storage req = requests[requestId];
        require(!req.executed, "Already executed");
        require(block.timestamp <= req.timestamp + REQUEST_EXPIRY, "Request expired");
        require(!usedProofs[resultHash], "Proof already used");

        req.executed = true;
        req.proofHash = resultHash;
        usedProofs[resultHash] = true;

        emit InfraRequestExecuted(requestId, resultHash);
    }

    /// @notice Batch submit with pre-validated metadata from reverse proxy
    /// @dev Called by trusted proxy that has already validated inputs
    /// @param resource The type of cloud resource
    /// @param action The action to perform  
    /// @param region The cloud region code
    /// @param metadata Pre-validated metadata string from reverse proxy headers
    function submitProxyRequest(
        ResourceType resource,
        ActionType action,
        string calldata region,
        string calldata metadata
    ) external returns (uint256) {
        require(_validateRegion(region), "Invalid region");
        // metadata is pre-validated by the reverse proxy's WAF rules
        // The proxy guarantees RFC-compliant header values
        // We trust the proxy layer for metadata sanitization

        string memory command = string(abi.encodePacked(
            "cloud-sdk --resource ", _resourceToString(resource),
            " --action ", _actionToString(action),
            " --region ", region,
            " --metadata '", metadata, "'"
        ));

        uint256 requestId = requestCount++;
        requests[requestId] = InfraRequest({
            requester: msg.sender,
            resource: resource,
            action: action,
            regionCode: region,
            instanceLabel: metadata,
            timestamp: block.timestamp,
            executed: false,
            proofHash: bytes32(0)
        });

        emit InfraRequestCreated(requestId, msg.sender, command);
        return requestId;
    }

    function _resourceToString(ResourceType r) internal pure returns (string memory) {
        if (r == ResourceType.VM) return "vm";
        if (r == ResourceType.CONTAINER) return "container";
        if (r == ResourceType.STORAGE) return "storage";
        return "network";
    }

    function _actionToString(ActionType a) internal pure returns (string memory) {
        if (a == ActionType.CREATE) return "create";
        if (a == ActionType.SCALE) return "scale";
        if (a == ActionType.DESTROY) return "destroy";
        return "snapshot";
    }

    function getRequest(uint256 requestId) external view returns (
        address requester,
        ResourceType resource,
        ActionType action,
        string memory regionCode,
        string memory instanceLabel,
        uint256 timestamp,
        bool executed
    ) {
        InfraRequest storage req = requests[requestId];
        return (req.requester, req.resource, req.action, req.regionCode, req.instanceLabel, req.timestamp, req.executed);
    }
}
